"""Exact Survivor, Harmony, Synergy, skill and Evolution Tree data from sIO.

The JSON is zlib-compressed only to keep generated source compact and prevent
manual JSON corruption.
"""
from __future__ import annotations

import base64
import json
import zlib

_COMPRESSED = ""
SIO_SURVIVOR_DATA = json.loads(zlib.decompress(base64.b64decode(_COMPRESSED)).decode("utf-8"))
